-- Code generated by factory from specs/receipts/list-store-ranking-top-n/spec.yaml. DO NOT EDIT.

-- name: ListStoreRankingTopN :many
SELECT t4.store_code, t4.total, t4.lines, t4.rank
FROM (
    SELECT t3.store_code AS store_code, t3.total AS total, t3.lines AS lines, t3.rank AS rank
    FROM (
        SELECT t2.store_code, t2.total, t2.lines, rank() OVER (ORDER BY t2.total DESC) AS rank
        FROM (
            SELECT t1.store_code AS store_code, coalesce(sum(t1.amount), 0) AS total, count(*) AS lines
            FROM sales_lines AS t1
            WHERE (t1.sales_date = sqlc.arg(sales_date)::date)
            GROUP BY t1.store_code
        ) AS t2
    ) AS t3
    WHERE (t3.rank <= sqlc.arg(top_n)::int4)
      AND ((sqlc.narg(min_total)::numeric IS NULL) OR (t3.total >= sqlc.narg(min_total)::numeric))
) AS t4
ORDER BY t4.rank, t4.store_code
LIMIT 1001;
